'use strict';

var assert = require('assert');
var bytes = require('..');

describe('proof', function () {
  it('keeps the 2-decimal default when an options object omits decimalPlaces', function () {
    assert.strictEqual(bytes(1536, {}), '1.5KB');
    assert.strictEqual(bytes(1536, { fixedDecimals: true }), '1.50KB');
    assert.strictEqual(bytes(1536, { decimalPlaces: undefined }), '1.5KB');
  });
});

import { describe, it } from 'node:test';
import assert from 'node:assert';
import { load } from 'js-yaml';

describe('proof', () => {
  it('fails on the patched build', () => {
    // Explicitly tagged signed binary integers must still load as numbers.
    // The patched explicit int pattern uses [^-+]? instead of [-+]? for the
    // 0b alternative, so signed binary sources no longer match and load throws.
    assert.strictEqual(load('!!int -0b101'), -5);
    assert.strictEqual(load('!!int +0b11'), 3);
  });
});

var assert = require('assert');
var ms = require('./');

describe('proof', function () {
  it('fails on the patched build', function () {
    // At exactly 1.5 units, ms 2.1.3's plural() (msAbs >= n * 1.5) uses the
    // plural form; the patched pluralize() (msAbs > n * 1.5) uses the singular.
    assert.strictEqual(ms(1500, { long: true }), '2 seconds');
    assert.strictEqual(ms(90000, { long: true }), '2 minutes');
    assert.strictEqual(ms(5400000, { long: true }), '2 hours');
    assert.strictEqual(ms(129600000, { long: true }), '2 days');
  });
});
